 'fases' => [
   ['indagar', 'Identificar las técnicas necesarias', 'Analiza los criterios de éxito y determina qué parte del problema exige una técnica no trivial. Investiga al menos dos alternativas para cada una.', 'Análisis con tres técnicas identificadas y dos alternativas por técnica.', 70],
   ['desarrollar', 'Justificar antes de implementar', 'Redacta la ficha de cada técnica con su justificación frente a las alternativas. Somete las fichas a revisión del docente antes de programar.', 'Tres fichas de técnica revisadas y aprobadas.', 60],
