['codigo' => 'VCP-12-07', 'titulo' => 'ITGS: estudio de caso de impacto social',
 'objeto' => 'el estudio de caso de impacto',
 'resumen' => 'Analizar un caso real de tecnología en la sociedad identificando partes interesadas, impactos y soluciones posibles.',
 'descripcion' => '<p>El estudiante analiza un caso real —vigilancia en el espacio público, algoritmos de contratación, automatización de un servicio— con el marco de ITGS: partes interesadas, escenario social, impactos positivos y negativos, y soluciones planteadas.</p><p>La exigencia es equilibrio: el análisis debe presentar la perspectiva de al menos tres partes interesadas con intereses en conflicto, incluida la de quien defiende la tecnología. Un análisis unilateral no cumple, por convincente que sea.</p>',
 'pregunta' => '¿Quién gana, quién pierde y quién decide cuando se introduce una tecnología?',
 'contexto' => 'Globalización y sustentabilidad', 'concepto' => 'Relaciones',
 'perfil' => 'De mentalidad abierta|Informado e instruido|Solidario', 'atl' => 'Pensamiento crítico|Alfabetización informacional|Comunicación',
 'objetivos' => 'Identificar partes interesadas y sus intereses en conflicto|Analizar impactos positivos y negativos con evidencia|Evaluar soluciones propuestas y sus límites|Sostener un análisis equilibrado con fuentes diversas',
 'entregables' => 'Análisis del caso con al menos seis fuentes|Mapa de tres partes interesadas con sus intereses|Evaluación de dos soluciones propuestas',
 'lenguaje' => 'Documentación', 'dificultad' => 'avanzado', 'sesiones' => 5, 'horas' => 6.0, 'ia' => 1,
 'codigo_inicial' => "// Marco de analisis ITGS\n// 1. Escenario y sistema de TI involucrado\n// 2. Partes interesadas y sus intereses (minimo tres, en conflicto)\n// 3. Impactos: sociales, eticos, economicos, ambientales\n// 4. Soluciones propuestas y sus limitaciones\n// 5. Evaluacion equilibrada con evidencia",
 'fases' => [
   ['indagar', 'Reunir fuentes diversas', 'Selecciona el caso y reúne seis fuentes que incluyan al menos una favorable a la tecnología y una crítica. Evalúa la credibilidad y el interés de cada fuente.', 'Seis fuentes evaluadas con su posición y credibilidad.', 70],
   ['desarrollar', 'Mapa de partes interesadas', 'Identifica tres partes interesadas con intereses en conflicto. Para cada una determina qué gana, qué pierde y qué poder de decisión tiene.', 'Mapa de partes interesadas con intereses y poder.', 60],
   ['crear', 'Redactar el análisis', 'Escribe el análisis siguiendo el marco: sistema, partes interesadas, impactos por categoría y soluciones propuestas. Toda afirmación con su fuente.', 'Análisis completo con las fuentes citadas correctamente.', 110],
   ['evaluar', 'Prueba de equilibrio', 'Pide a un compañero que identifique tu posición leyendo solo el análisis. Si la detecta fácilmente, revisa dónde perdiste el equilibrio y corrige.', 'Registro de la prueba de equilibrio y correcciones aplicadas.', 55],
 ],
 'recursos' => [
   ['plantilla', 'Marco de análisis ITGS', 'Estructura de cinco secciones con preguntas guía.'],
   ['plantilla', 'Evaluación de credibilidad de fuentes', 'Autoría, interés, evidencia, fecha.'],
 ]],

['codigo' => 'VCP-12-08', 'titulo' => 'Concurrencia y sistemas distribuidos',
 'objeto' => 'el programa concurrente',
 'resumen' => 'Programar tareas concurrentes, provocar una condición de carrera y resolverla con sincronización.',
 'descripcion' => '<p>Contenido de Nivel Superior. El estudiante escribe un programa con varios hilos que comparten un recurso, provoca deliberadamente una condición de carrera y comprueba que el resultado varía entre ejecuciones aunque el código no cambie.</p><p>Después aplica sincronización y verifica que el resultado se vuelve determinista, midiendo el costo en rendimiento. La actividad cierra con el problema de los interbloqueos: el estudiante provoca uno y explica las cuatro condiciones que lo hacen posible.</p>',
 'pregunta' => '¿Por qué el mismo programa da resultados distintos cada vez que lo ejecuto?',
 'contexto' => 'Innovación científica y técnica', 'concepto' => 'Sistemas',
 'perfil' => 'Pensador|Indagador', 'atl' => 'Pensamiento crítico|Transferencia',
 'objetivos' => 'Crear y coordinar hilos de ejecución|Provocar y explicar una condición de carrera|Aplicar sincronización y medir su costo|Identificar las condiciones de un interbloqueo',
 'entregables' => 'Programa con condición de carrera demostrada en veinte ejecuciones|Versión sincronizada con resultado determinista|Análisis del interbloqueo provocado',
 'lenguaje' => 'Java', 'dificultad' => 'avanzado', 'sesiones' => 5, 'horas' => 6.0, 'ia' => 1,
 'codigo_inicial' => "public class Contador {\n    private int valor = 0;\n\n    public void incrementar() {\n        valor++;   // no es atomico: leer, sumar, escribir\n    }\n\n    public int getValor() { return valor; }\n}\n\n// TODO: lanza 10 hilos que incrementen 1000 veces cada uno\n// TODO: ejecuta 20 veces y registra los resultados\n// TODO: sincroniza y vuelve a medir",
 'fases' => [
   ['indagar', 'Fallos de concurrencia reales', 'Investiga un fallo documentado causado por una condición de carrera. Determina qué recurso se compartía y qué consecuencia tuvo.', 'Estudio de un caso con el mecanismo técnico identificado.', 50],
